(function(){'use strict';
const KEY='nawaf-hq-v5';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const now=()=>new Date().toISOString();
const uid=p=>p+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const activeStates=new Set(['WORKING','RESEARCHING','REVIEWING']);
const PAGE_MAP={workforce:'employees',projects:'projects',tasks:'tasks',reports:'activity'};
const extraPages=[['ceo','مركز CEO','⌁'],['secretary','السكرتير التنفيذي','✦'],['finance','المالية','◫'],['integrations','التكاملات','⌘'],['apps','التطبيقات','▣'],['settings','الإعدادات','⚙']];
const labels={READY:'جاهز',IDLE:'متاح',WORKING:'يعمل',RESEARCHING:'يبحث',REVIEWING:'يراجع',WAITING_FOR_NAWAF:'بانتظار نواف',WAITING_FOR_CONNECTION:'بانتظار اتصال',BLOCKED:'متعثر',BLOCKED_BY_TOOL:'يحتاج أداة',PAUSED:'متوقف',COMPLETED:'مكتمل'};
let page=null,taskQuery={text:'',status:'ALL',project:'ALL',employee:'ALL'},activityFilter='ALL',integrationCache=null;
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function ensure(s){for(const k of ['employees','projects','tasks','reports','activity','approvals','connectionRequests','notifications','archives'])if(!Array.isArray(s[k]))s[k]=[];s.settings=s.settings&&typeof s.settings==='object'?s.settings:{};s.finance=s.finance&&typeof s.finance==='object'?s.finance:{};return s}
function audit(s,text,type='MANAGEMENT'){s.activity.unshift({id:uid('a'),text,type,at:now()});s.activity=s.activity.slice(0,250)}
function write(s,reason='v24'){s.companyUpdatedAt=now();localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason}}))}
function status(v){return labels[v]||v||'جاهز'}
function ago(v){const n=Date.parse(v||'');if(!Number.isFinite(n))return 'بدون وقت';const m=Math.max(0,Math.floor((Date.now()-n)/60000));return m<1?'الآن':m<60?`منذ ${m} د`:m<1440?`منذ ${Math.floor(m/60)} س`:`منذ ${Math.floor(m/1440)} ي`}
function evidence(t){return Array.isArray(t?.evidence)?t.evidence:[]}
function commit(t){return t?.executionCommit||t?.applyEvidence?.commitSha||t?.aiResult?.applyEvidence?.commitSha||t?.aiResult?.projectExecution?.commitSha||''}
function qa(t){if(!t)return 'غير متاح';if(t.qaGate?.passed||t.qaPassed===true||t.aiResult?.qaPassed===true||t.aiResult?.verificationPassed===true)return 'ناجح';if(t.qaGate?.required)return 'يحتاج تحقق';return 'غير مطلوب'}
function stage(t){const log=Array.isArray(t?.executionLog)?t.executionLog:[];return log.at(-1)?.stage||({READY:'QUEUED',WORKING:'EXECUTING',RESEARCHING:'RESEARCH',REVIEWING:'QA',WAITING_FOR_NAWAF:'APPROVAL',WAITING_FOR_CONNECTION:'CONNECTION',BLOCKED:'FAILED',BLOCKED_BY_TOOL:'TOOL_BLOCK',PAUSED:'PAUSED',COMPLETED:'VERIFIED'})[t?.status]||'QUEUED'}
function projectLinks(p){const known={mueen:{live:'https://mueen-islamic-app.vercel.app/',repo:'https://github.com/uauz1/mueen-islamic-app'},qaddha:{live:'https://qaddha.vercel.app/',repo:'https://github.com/uauz1/game'}}[p.id]||{};return {live:p.liveUrl||known.live||'',repo:p.repoUrl||known.repo||''}}
function icon(name){return ({employees:'◉',projects:'◇',tasks:'✓',activity:'≋',ceo:'⌁',secretary:'✦',finance:'◫',integrations:'⌘',apps:'▣',settings:'⚙'})[name]||'•'}
function notify(text){let t=$('#v24-toast');if(!t){t=document.createElement('div');t.id='v24-toast';document.body.appendChild(t)}t.textContent=text;t.classList.add('show');clearTimeout(notify.t);notify.t=setTimeout(()=>t.classList.remove('show'),2400)}
function modal(title,html,wide=false){let m=$('#v24-modal');if(!m){m=document.createElement('div');m.id='v24-modal';m.className='v24-modal';m.innerHTML='<div class="v24-dialog"><button class="v24-x" data-v24-close>×</button><header><span>NAWAF HQ</span><h2></h2></header><main></main></div>';document.body.appendChild(m);m.onclick=e=>{if(e.target===m||e.target.closest('[data-v24-close]'))m.classList.remove('show')}}m.querySelector('h2').textContent=title;m.querySelector('main').innerHTML=html;m.querySelector('.v24-dialog').classList.toggle('wide',wide);m.classList.add('show');return m}
function top(kicker,title,sub,actions=''){return `<header class="v24-top"><div><span>${esc(kicker)}</span><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="v24-top-actions">${actions}</div></header>`}
function empty(title,sub){return `<div class="v24-empty"><i>◇</i><b>${esc(title)}</b><span>${esc(sub)}</span></div>`}
function kpis(items){return `<section class="v24-kpis">${items.map(x=>`<article><small>${esc(x[0])}</small><b>${esc(x[1])}</b><span>${esc(x[2]||'')}</span></article>`).join('')}</section>`}
function mountMobileMenu(nav){if(nav.querySelector('#v24-mobile-more'))return;document.querySelector('#v24-mobile-menu')?.remove();const more=document.createElement('button');more.type='button';more.id='v24-mobile-more';more.setAttribute('aria-label','المزيد من أقسام الشركة');more.setAttribute('aria-expanded','false');more.innerHTML='<i>•••</i><span>المزيد</span>';nav.appendChild(more);const menu=document.createElement('section');menu.id='v24-mobile-menu';menu.setAttribute('aria-hidden','true');menu.innerHTML=`<header><span>أقسام الشركة</span><button type="button" data-v24-mobile-close aria-label="إغلاق">×</button></header><main>${[['activity','التقارير','≋'],...extraPages].map(([id,label,ico])=>`<button type="button" data-v24-mobile-page="${id}"><i>${ico}</i><span>${label}</span></button>`).join('')}</main>`;document.body.appendChild(menu);more.onclick=()=>{const open=!menu.classList.contains('show');menu.classList.toggle('show',open);menu.setAttribute('aria-hidden',String(!open));more.setAttribute('aria-expanded',String(open))};menu.onclick=e=>{if(e.target.closest('[data-v24-mobile-close]')){menu.classList.remove('show');menu.setAttribute('aria-hidden','true');more.setAttribute('aria-expanded','false');return}const b=e.target.closest('[data-v24-mobile-page]');if(!b)return;activate(b.dataset.v24MobilePage);menu.classList.remove('show');menu.setAttribute('aria-hidden','true');more.setAttribute('aria-expanded','false')}}
function mountNav(){const nav=$('.v8-side nav');if(!nav)return;if(!nav.querySelector('[data-v24-page]')){const sep=document.createElement('div');sep.className='v24-nav-sep';sep.innerHTML='<span>إدارة الشركة</span>';nav.appendChild(sep);for(const [id,label,ico] of extraPages){const b=document.createElement('button');b.type='button';b.dataset.v24Page=id;b.innerHTML=`<i>${ico}</i><span>${label}</span>`;nav.appendChild(b)}}mountMobileMenu(nav);markNav()}
function markNav(){document.querySelectorAll('[data-v24-page],[data-v24-mobile-page]').forEach(b=>b.classList.toggle('active',(b.dataset.v24Page||b.dataset.v24MobilePage)===page));const more=$('#v24-mobile-more');if(more)more.classList.toggle('active',page!==null&&page!=='employees'&&page!=='projects'&&page!=='tasks');const inverse={employees:'workforce',projects:'projects',tasks:'tasks',activity:'reports'};document.querySelectorAll('.v8-side [data-view]').forEach(b=>b.classList.toggle('active',page?b.dataset.view===inverse[page]:b.dataset.view==='dashboard'))}
function main(){return $('.v8-main')}
function render(){const root=main();if(!root||!page)return;document.body.classList.add('v24-active');root.dataset.v24Page=page;const s=ensure(read());const fn={employees,projects,tasks,activity,ceo,secretary,finance,integrations,apps,settings}[page];root.innerHTML=`<section class="v24-workspace">${fn?fn(s):''}</section>`;markNav();bind(root);if(page==='integrations')loadIntegrations()}
function activate(id){page=id;render()}

function employees(s){const list=s.employees.filter(e=>!e.deletedAt),working=list.filter(e=>activeStates.has(e.status)).length,blocked=list.filter(e=>['BLOCKED','BLOCKED_BY_TOOL','WAITING_FOR_CONNECTION'].includes(e.status)).length;return `${top('AI WORKFORCE','إدارة الموظفين','ملفات وصلاحيات وأدوات وسجل تنفيذ من نفس محرك الشركة.',`<button class="v24-btn" data-action="new-employee">＋ موظف جديد</button>`)}${kpis([['إجمالي الفريق',list.length,'ملفات مفعلة'],['يعمل الآن',working,'حالة حقيقية'],['متاح',list.filter(e=>['READY','IDLE'].includes(e.status)).length,'جاهز للتكليف'],['يحتاج انتباه',blocked,'عائق مسجل']])}<div class="v24-employee-grid">${list.map(e=>{const et=s.tasks.filter(t=>t.employeeId===e.id),cur=et.find(t=>activeStates.has(t.status)||t.status.startsWith('WAITING')),done=et.filter(t=>t.status==='COMPLETED').length;return `<button class="v24-employee" data-v24-employee="${esc(e.id)}" style="--accent:${esc(e.accent||'#70a7ff')}"><div class="v24-avatar">${esc(e.avatar||e.name?.slice(0,1)||'AI')}</div><div class="v24-person-head"><span><b>${esc(e.name)}</b><small>${esc(e.role||e.department||'موظف AI')}</small></span><i class="state-${esc(e.status)}">${esc(e.disabled?'معطل':status(e.status))}</i></div><p>${esc(cur?.title||e.task||e.description||'متاح لمهمة جديدة')}</p><footer><span>${et.length} مهام</span><span>${done} مكتملة</span><span>${evidence(et[0]).length} دليل حديث</span></footer></button>`}).join('')||empty('لا يوجد موظفون','أضف أول موظف للبدء.')}</div>`}
function openEmployee(id){const s=ensure(read()),e=s.employees.find(x=>x.id===id&&!x.deletedAt);if(!e)return;const et=s.tasks.filter(t=>t.employeeId===id),current=et.find(t=>activeStates.has(t.status)||t.status.startsWith('WAITING')),recent=et.slice(0,6),projects=s.projects.filter(p=>(e.projectIds||[e.projectId]).includes(p.id));const m=modal(`ملف ${e.name}`,`<div class="v24-profile"><aside><div class="v24-profile-avatar">${esc(e.avatar||e.name?.slice(0,1)||'AI')}</div><b>${esc(e.name)}</b><span>${esc(status(e.status))}</span><small>${esc(e.department||'بدون قسم')}</small><button class="v24-btn primary" data-v24-direct="${esc(id)}">إعطاء أمر مباشر</button><button class="v24-btn" data-v24-assign="${esc(id)}">تعيين مهمة</button></aside><section><div class="v24-profile-stats"><div><b>${et.length}</b><span>المهام</span></div><div><b>${et.filter(t=>t.status==='COMPLETED').length}</b><span>مكتملة</span></div><div><b>${et.filter(t=>['BLOCKED','BLOCKED_BY_TOOL'].includes(t.status)).length}</b><span>متعثر</span></div><div><b>${activeStates.has(e.status)?'مشغول':'متاح'}</b><span>التوفر</span></div></div><div class="v24-current"><small>التكليف الحالي</small><b>${esc(current?.title||'لا يوجد تكليف نشط')}</b><span>${esc(current?.blockedReason||current?.status||'READY')}</span></div><form id="v24-employee-edit" class="v24-form"><input type="hidden" name="id" value="${esc(id)}"><label>الاسم<input name="name" value="${esc(e.name)}" required></label><label>المسمى<input name="role" value="${esc(e.role||'')}"></label><label>القسم<input name="department" value="${esc(e.department||'')}"></label><label>لون الموظف<input name="accent" type="color" value="${esc(e.accent||'#70a7ff')}"></label><label class="full">الوصف<textarea name="description">${esc(e.description||e.mission||'')}</textarea></label><label class="full">المهارات (مفصولة بفاصلة)<input name="skills" value="${esc((e.skills||[]).join(', '))}"></label><label class="full">التعليمات الخاصة<textarea name="instructions">${esc(e.instructions||'')}</textarea></label><fieldset class="full"><legend>الصلاحيات</legend>${['research','code','qa','finance','reports','deploy'].map(p=>`<label class="check"><input type="checkbox" name="perm" value="${p}" ${(e.permissions||[]).includes(p)?'checked':''}>${p}</label>`).join('')}</fieldset><div class="full v24-form-actions"><button class="v24-btn primary" type="submit">حفظ الملف</button><button class="v24-btn" type="button" data-v24-duplicate="${esc(id)}">نسخ الملف</button><button class="v24-btn" type="button" data-v24-toggle="${esc(id)}">${e.disabled?'تفعيل':'تعطيل مؤقت'}</button>${String(id).startsWith('emp')?`<button class="v24-btn danger" type="button" data-v24-delete-employee="${esc(id)}">حذف آمن</button>`:''}</div></form><h3>آخر التنفيذات</h3><div class="v24-mini-list">${recent.map(t=>`<button data-v24-task="${esc(t.id)}"><span><b>${esc(t.title)}</b><small>${esc(stage(t))} · ${esc(ago(t.updatedAt||t.createdAt))}</small></span><i>${esc(status(t.status))}</i></button>`).join('')||'<p>لا توجد مهام بعد.</p>'}</div><p class="v24-meta">المشاريع: ${projects.map(p=>esc(p.name)).join('، ')||'غير محدد'} · الأدوات: ${(e.tools||[]).map(esc).join('، ')||'حسب صلاحية المحرك'}</p></section></div>`,true);bind(m)}

function projects(s){return `${top('PROJECT PORTFOLIO','المشاريع','الصحة والمهام والدليل والتشغيل في مكان واحد.',`<a class="v24-btn" href="apps.html">مركز التطبيقات</a>`)}<div class="v24-project-list">${s.projects.map(p=>{const pt=s.tasks.filter(t=>t.projectId===p.id),done=pt.filter(t=>t.status==='COMPLETED'),blocked=pt.filter(t=>['BLOCKED','BLOCKED_BY_TOOL','WAITING_FOR_CONNECTION'].includes(t.status)),latest=pt.sort((a,b)=>Date.parse(b.updatedAt||b.createdAt||0)-Date.parse(a.updatedAt||a.createdAt||0))[0],c=done.map(commit).find(Boolean),links=projectLinks(p);return `<article class="v24-project"><header><div class="v24-project-mark">${esc(p.name?.slice(0,1)||'P')}</div><div><span>${esc(p.stage||p.phase||'جاهز للعمل')}</span><h2>${esc(p.name)}</h2><p>${esc(p.description||'مشروع مرتبط بنظام تشغيل الشركة')}</p></div><i class="state-${esc(p.status)}">${esc(p.status||'ACTIVE')}</i></header><div class="v24-project-facts"><div><small>الصحة</small><b>${blocked.length?'يحتاج انتباه':'مستقر'}</b></div><div><small>نشطة</small><b>${pt.filter(t=>activeStates.has(t.status)).length}</b></div><div><small>مكتملة</small><b>${done.length}</b></div><div><small>موافقات</small><b>${pt.filter(t=>t.status==='WAITING_FOR_NAWAF').length}</b></div><div><small>آخر QA</small><b>${esc(qa(latest))}</b></div><div><small>آخر Commit</small><b title="${esc(c)}">${esc(c?c.slice(0,8):'—')}</b></div></div><div class="v24-stage-line">${['QUEUED','EXECUTING','QA','VERIFIED'].map(x=>`<span class="${stage(latest)===x?'active':''}">${x}</span>`).join('')}</div><footer>${links.live?`<a href="${esc(links.live)}" target="_blank" rel="noopener">فتح التطبيق</a>`:''}${links.repo?`<a href="${esc(links.repo)}" target="_blank" rel="noopener">GitHub</a>`:''}<button data-v24-project-task="${esc(p.id)}">إنشاء مهمة</button><button data-v24-project-qa="${esc(p.id)}">تشغيل QA</button><button data-v24-project-report="${esc(p.id)}">تقرير</button><button data-v24-project="${esc(p.id)}">التفاصيل</button></footer></article>`}).join('')||empty('لا توجد مشاريع','أضف مشروعًا مرتبطًا بالشركة.')}</div>`}
function openProject(id){const s=ensure(read()),p=s.projects.find(x=>x.id===id);if(!p)return;const pt=s.tasks.filter(t=>t.projectId===id),links=projectLinks(p),latestCommit=pt.map(commit).find(Boolean),lastQa=pt.find(t=>qa(t)==='ناجح');modal(p.name,`<div class="v24-detail-grid"><article><small>الحالة</small><b>${esc(p.status||'ACTIVE')}</b></article><article><small>المرحلة</small><b>${esc(p.stage||p.phase||'—')}</b></article><article><small>آخر نشر</small><b>${esc(p.latestDeployment||'غير موثق')}</b></article><article><small>آخر Commit</small><b>${esc(latestCommit||'غير متاح')}</b></article><article><small>آخر QA</small><b>${esc(lastQa?ago(lastQa.updatedAt||lastQa.createdAt):'لا يوجد')}</b></article><article><small>الموظفون</small><b>${new Set(pt.map(t=>t.employeeId).filter(Boolean)).size}</b></article></div><div class="v24-form-actions">${links.live?`<a class="v24-btn primary" href="${esc(links.live)}" target="_blank">فتح التطبيق</a>`:''}${links.repo?`<a class="v24-btn" href="${esc(links.repo)}" target="_blank">فتح المستودع</a>`:''}<button class="v24-btn" data-v24-project-task="${esc(id)}">مهمة جديدة</button><button class="v24-btn" data-v24-project-qa="${esc(id)}">تشغيل QA</button></div><h3>آخر المهام</h3><div class="v24-mini-list">${pt.slice(0,12).map(taskButton).join('')||'<p>لا توجد مهام.</p>'}</div>`,true)}

function taskButton(t){return `<button data-v24-task="${esc(t.id)}"><span><b>${esc(t.title)}</b><small>${esc(stage(t))} · ${esc(ago(t.updatedAt||t.createdAt))}</small></span><i class="state-${esc(t.status)}">${esc(status(t.status))}</i></button>`}
function tasks(s){const filtered=s.tasks.filter(t=>!t.archivedAt).filter(t=>taskQuery.status==='ALL'||t.status===taskQuery.status).filter(t=>taskQuery.project==='ALL'||t.projectId===taskQuery.project).filter(t=>taskQuery.employee==='ALL'||t.employeeId===taskQuery.employee).filter(t=>!taskQuery.text||(t.title+' '+(t.details||'')).toLowerCase().includes(taskQuery.text.toLowerCase())).sort((a,b)=>Date.parse(b.updatedAt||b.createdAt||0)-Date.parse(a.updatedAt||a.createdAt||0));const all=s.tasks.filter(t=>!t.archivedAt),attention=all.filter(t=>['WAITING_FOR_NAWAF','WAITING_FOR_CONNECTION','BLOCKED','BLOCKED_BY_TOOL'].includes(t.status)).length,active=all.filter(t=>activeStates.has(t.status)).length,done=all.filter(t=>t.status==='COMPLETED').length;return `${top('EXECUTION PIPELINE','المهام','تقدم مرحلي صادق، أدلة، عوائق، وإجراءات تنفيذ آمنة.',`<button class="v24-btn primary" data-action="new-task">＋ مهمة جديدة</button>`)}<section class="v24-task-pulse"><button data-v24-task-preset="ALL"><b>${all.length}</b><span>كل المهام</span></button><button data-v24-task-preset="ACTIVE"><b>${active}</b><span>يعمل الآن</span></button><button data-v24-task-preset="ATTENTION"><b>${attention}</b><span>تحتاج انتباه</span></button><button data-v24-task-preset="COMPLETED"><b>${done}</b><span>مكتملة</span></button></section><section class="v24-filter"><input data-v24-task-search value="${esc(taskQuery.text)}" placeholder="ابحث في المهام..."><select data-v24-task-filter="status"><option value="ALL">كل الحالات</option>${Object.keys(labels).map(x=>`<option value="${x}" ${taskQuery.status===x?'selected':''}>${status(x)}</option>`).join('')}</select><select data-v24-task-filter="project"><option value="ALL">كل المشاريع</option>${s.projects.map(p=>`<option value="${esc(p.id)}" ${taskQuery.project===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select data-v24-task-filter="employee"><option value="ALL">كل الموظفين</option>${s.employees.filter(e=>!e.deletedAt).map(e=>`<option value="${esc(e.id)}" ${taskQuery.employee===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></section><div class="v24-task-table"><header><span>المهمة</span><span>المسؤول / المشروع</span><span>مرحلة التنفيذ</span><span>الحالة</span><span>الدليل</span><span></span></header>${filtered.map(t=>{const e=s.employees.find(x=>x.id===t.employeeId),p=s.projects.find(x=>x.id===t.projectId);return `<article class="v24-task-row" data-v24-task="${esc(t.id)}" tabindex="0" role="button"><button class="v24-task-title" type="button"><b>${esc(t.title)}</b><small>${esc(ago(t.updatedAt||t.createdAt))}</small></button><span>${esc(e?.name||'غير مسند')}<small>${esc(p?.name||'عام')}</small></span><span><b>${esc(stage(t))}</b><small>${esc((t.dependsOn||[]).length?`${t.dependsOn.length} اعتماديات`:'بلا اعتماديات')}</small></span><i class="state-${esc(t.status)}">${esc(status(t.status))}</i><span><b>${evidence(t).length}</b><small>${commit(t)?`commit ${esc(commit(t).slice(0,7))}`:qa(t)}</small></span><button class="v24-more" type="button" aria-label="فتح تفاصيل المهمة">فتح</button></article>`}).join('')||empty('لا توجد نتائج','غيّر الفلاتر أو أنشئ مهمة جديدة.')}</div>`}
function openTask(id){const s=ensure(read()),t=s.tasks.find(x=>x.id===id);if(!t)return;const e=s.employees.find(x=>x.id===t.employeeId),p=s.projects.find(x=>x.id===t.projectId),logs=t.executionLog||[],ev=evidence(t),out=t.aiResult?.deliverable||t.aiResult?.summary||'';const canRetry=['BLOCKED','BLOCKED_BY_TOOL','WAITING_FOR_CONNECTION'].includes(t.status),canPause=activeStates.has(t.status)||t.status==='READY',canResume=t.status==='PAUSED';modal(t.title,`<div class="v24-task-detail"><div class="v24-detail-grid"><article><small>الموظف</small><b>${esc(e?.name||'غير مسند')}</b></article><article><small>المشروع</small><b>${esc(p?.name||'عام')}</b></article><article><small>الحالة</small><b>${esc(status(t.status))}</b></article><article><small>المرحلة</small><b>${esc(stage(t))}</b></article><article><small>QA</small><b>${esc(qa(t))}</b></article><article><small>المحاولات</small><b>${esc(t.retryCount||0)}</b></article></div><section><h3>التعليمات</h3><p>${esc(t.details||t.title)}</p></section>${t.blockedReason?`<section class="warning"><h3>العائق الحقيقي</h3><p>${esc(t.blockedReason)}</p><small>الأداة المطلوبة: ${esc((t.requiredTools||[]).join('، ')||'غير محددة')}</small></section>`:''}${out?`<section><h3>النتيجة</h3><pre>${esc(out)}</pre></section>`:''}<section><h3>الأدلة (${ev.length})</h3>${ev.map(x=>`<p>${esc(x.text||x)}</p>`).join('')||'<p>لا يوجد دليل محفوظ.</p>'}${commit(t)?`<code>${esc(commit(t))}</code>`:''}</section><section><h3>سجل التنفيذ</h3>${logs.map(x=>`<p><b>${esc(x.stage)}</b> — ${esc(x.detail||'')} <small>${esc(ago(x.at))}</small></p>`).join('')||'<p>لم يبدأ التنفيذ بعد.</p>'}</section><div class="v24-form-actions">${canRetry?`<button class="v24-btn primary" data-v24-task-action="retry" data-id="${esc(id)}">إعادة محاولة</button>`:''}${canPause?`<button class="v24-btn" data-v24-task-action="pause" data-id="${esc(id)}">إيقاف مؤقت</button>`:''}${canResume?`<button class="v24-btn primary" data-v24-task-action="resume" data-id="${esc(id)}">استئناف</button>`:''}<button class="v24-btn" data-v24-reassign="${esc(id)}">إعادة تعيين</button><button class="v24-btn" data-v24-copy="${esc(id)}">نسخ النتيجة</button><button class="v24-btn" data-v24-task-action="archive" data-id="${esc(id)}">أرشفة</button></div></div>`,true)}

function ceo(s){const needs=s.tasks.filter(t=>['WAITING_FOR_NAWAF','WAITING_FOR_CONNECTION','BLOCKED','BLOCKED_BY_TOOL'].includes(t.status)),recent=s.tasks.filter(t=>t.status==='COMPLETED').slice(0,8),priority=[...needs].sort((a,b)=>(b.priority==='HIGH')-(a.priority==='HIGH'));return `${top('CEO CONTROL','مركز قرارات نواف','كل ما يحتاج موافقة أو اتصال أو معلومة، مع السبب والأثر.',`<button class="v24-btn primary" data-v24-open-decisions>فتح صندوق الموافقات</button>`)}${kpis([['يحتاج موافقة',needs.filter(t=>t.status==='WAITING_FOR_NAWAF').length,'قرار مباشر'],['يحتاج اتصال',needs.filter(t=>t.status==='WAITING_FOR_CONNECTION').length,'خدمة خارجية'],['متعثر',needs.filter(t=>['BLOCKED','BLOCKED_BY_TOOL'].includes(t.status)).length,'سبب مسجل'],['اكتمل مؤخرًا',recent.length,'بنتائج محفوظة']])}<section class="v24-split"><article class="v24-panel"><header><span>ATTENTION REQUIRED</span><h2>الأولوية الآن</h2></header><div class="v24-decision-list">${priority.map(t=>`<button data-v24-task="${esc(t.id)}"><span class="risk ${t.status==='WAITING_FOR_NAWAF'?'high':'medium'}">${t.status==='WAITING_FOR_NAWAF'?'قرار':'متابعة'}</span><div><b>${esc(t.title)}</b><small>${esc(t.blockedReason||status(t.status))}</small><em>${esc(s.employees.find(e=>e.id===t.employeeId)?.name||'غير مسند')} · ${esc(s.projects.find(p=>p.id===t.projectId)?.name||'عام')}</em></div><strong>فتح</strong></button>`).join('')||empty('لا شيء يحتاج قرارك','كل العمليات الحالية واضحة.')}</div></article><article class="v24-panel"><header><span>RECENTLY VERIFIED</span><h2>اكتمل مؤخرًا</h2></header><div class="v24-mini-list">${recent.map(taskButton).join('')||empty('لا يوجد اكتمال حديث','ستظهر النتائج الموثقة هنا.')}</div></article></section>`}
function secretary(s){const done=s.tasks.filter(t=>t.status==='COMPLETED'),today=new Date().toISOString().slice(0,10),todayDone=done.filter(t=>String(t.executionFinishedAt||t.updatedAt||t.createdAt).startsWith(today)),failed=s.tasks.filter(t=>['BLOCKED','BLOCKED_BY_TOOL'].includes(t.status)),briefs=done.slice(0,12).map(t=>{const e=s.employees.find(x=>x.id===t.employeeId),p=s.projects.find(x=>x.id===t.projectId);return {t,e,p,report:s.reports.find(r=>r.sourceTaskId===t.id)}});return `${top('EXECUTIVE SECRETARY','السكرتير التنفيذي','ملخصات مبنية فقط على تنفيذ ونتائج وأدلة مسجلة.',`<button class="v24-btn" data-v24-morning>الملخص اليومي</button>`)}${kpis([['مكتمل اليوم',todayDone.length,'نتائج موثقة'],['فشل اليوم',failed.filter(t=>String(t.updatedAt||t.executionFinishedAt||'').startsWith(today)).length,'يحتاج متابعة'],['انتباه مطلوب',s.tasks.filter(t=>t.status.startsWith('WAITING')).length,'قرارات واتصالات'],['تقارير محفوظة',s.reports.length,'مخرجات الشركة']])}<div class="v24-briefs">${briefs.map(({t,e,p,report})=>`<article><header><span>${esc(p?.name||'الشركة')}</span><time>${esc(ago(t.executionFinishedAt||t.updatedAt))}</time></header><h2>${esc(t.title)}</h2><dl><div><dt>من نفّذ</dt><dd>${esc(e?.name||'موظف AI')}</dd></div><div><dt>النتيجة</dt><dd>${esc(t.aiResult?.summary||report?.content?.slice(0,180)||'اكتملت المهمة وسُجلت النتيجة.')}</dd></div><div><dt>الدليل</dt><dd>${evidence(t).length} أدلة ${commit(t)?`· ${esc(commit(t).slice(0,8))}`:''}</dd></div><div><dt>QA</dt><dd>${esc(qa(t))}</dd></div></dl><button data-v24-task="${esc(t.id)}">فتح المهمة والأدلة</button></article>`).join('')||empty('لا توجد ملخصات حقيقية بعد','تظهر الملخصات بعد اكتمال مهمة فعلية فقط.')}</div>`}
function finance(s){const f=s.finance||{},tr=s.trading||{},orders=tr.orders||f.orders||[],tx=tr.transactions||f.transactions||[],watch=f.watchlist||[];return `${top('FINANCE · PAPER ONLY','المركز المالي','تحليل وتمويل شركة ومحاكاة ورقية فقط — بدون أموال حقيقية.',`<button class="v24-btn primary" data-v24-finance-open>فتح المحلل المالي</button>`)}<div class="v24-paper">PAPER / ANALYSIS ONLY · لا شراء أو بيع أو تحويل أموال حقيقي</div>${kpis([['الرصيد النقدي',f.cashBalance??tr.cashBalance??'—',f.currency||'غير موثق'],['قيمة المحفظة',f.portfolioValue??tr.portfolioValue??'—','بيانات ورقية'],['ربح/خسارة غير محققة',f.unrealizedPL??'—','ورقي'],['ربح/خسارة محققة',f.realizedPL??'—','ورقي']])}<section class="v24-split"><article class="v24-panel"><header><span>WATCHLIST</span><h2>قائمة المراقبة</h2></header><div class="v24-mini-list">${watch.map(x=>`<button data-v24-finance-symbol="${esc(x.symbol)}"><span><b>${esc(x.symbol)}</b><small>${esc(x.name||'تحليل مالي')}</small></span><i>${esc(x.price??'—')}</i></button>`).join('')||empty('القائمة فارغة','أضف رمزًا من المحلل المالي.')}</div></article><article class="v24-panel"><header><span>PAPER ORDERS</span><h2>الأوامر والمعاملات</h2></header><div class="v24-mini-list">${[...orders,...tx].slice(0,10).map(x=>`<div><span><b>${esc(x.symbol||x.title||'عملية ورقية')}</b><small>${esc(x.side||x.type||'PAPER')} · ${esc(ago(x.at||x.createdAt))}</small></span><i>${esc(x.status||'مسجل')}</i></div>`).join('')||empty('لا توجد عمليات','لن تظهر أي عملية غير مسجلة.')}</div></article></section>`}

function integrations(){const loading=!integrationCache;return `${top('CONNECTED SYSTEMS','التكاملات','حالة حقيقية من فحص الخدمات، بدون حالات اتصال تجميلية.',`<button class="v24-btn" data-v24-refresh-integrations>إعادة الفحص</button>`)}<div id="v24-integrations">${loading?'<div class="v24-loading">جاري فحص الخدمات الفعلية…</div>':integrationRows(integrationCache)}</div>`}
function integrationRows(data){return `<div class="v24-integration-grid">${data.map(x=>`<article><div class="v24-integration-icon">${esc(x.icon||'⌘')}</div><div><h2>${esc(x.name)}</h2><p>${esc(x.detail||'')}</p><small>آخر فحص: ${esc(x.checked||'الآن')}</small></div><i class="${x.state}">${x.state==='ok'?'متصل':x.state==='warn'?'يحتاج انتباه':'غير متصل'}</i><footer><span>${esc(x.permissions||'حسب إعداد المزود')}</span>${x.action?`<button data-v24-integration-action="${esc(x.action)}">${x.state==='ok'?'فحص':'ربط / إصلاح'}</button>`:''}</footer></article>`).join('')}</div>`}
async function loadIntegrations(force=false){if(integrationCache&&!force){const box=$('#v24-integrations');if(box)box.innerHTML=integrationRows(integrationCache);return}const checked=new Date().toLocaleTimeString('ar-SA',{hour:'2-digit',minute:'2-digit'});const [health,trading]=await Promise.all([fetch('/api/health',{cache:'no-store'}).then(async r=>({ok:r.ok,data:await r.json().catch(()=>({}))})).catch(()=>({ok:false,data:{}})),fetch('/api/trading/status',{cache:'no-store'}).then(async r=>({ok:r.ok,data:await r.json().catch(()=>({}))})).catch(()=>({ok:false,data:{}}))]);const d=health.data||{},e=d.engine||{};integrationCache=[{name:'محرك الشركة',state:health.ok?'ok':'off',detail:d.service||'تعذر الوصول إلى /api/health',checked,icon:'⌁',action:'health'},{name:'Cloud State',state:d.cloudState?'ok':'warn',detail:d.cloudState?'مزامنة مركزية مفعلة':'غير مؤكد من الخادم',checked,icon:'☁',action:'sync'},{name:'GitHub',state:/CONNECTED|READY|OK/i.test(String(e.githubPrivateRepo||''))?'ok':'warn',detail:e.githubPrivateRepo||'صلاحية المستودع غير مؤكدة',checked,icon:'⌘',action:'github'},{name:'Gemini',state:e.gemini==='CONNECTED'?'ok':'warn',detail:e.gemini||'غير متصل',checked,icon:'✦',action:'gemini'},{name:'Supabase',state:d.cloudState?'ok':'warn',detail:d.cloudState?'مستخدم لحالة الشركة':'تحقق من متغيرات الخادم',checked,icon:'◈',action:'supabase'},{name:'Slack',state:d.slack?'ok':'off',detail:d.slack?'الإشعارات مفعلة':'غير مهيأ',checked,icon:'#',action:'slack'},{name:'Project Execution',state:d.projectExecution?'ok':'off',detail:d.projectExecution?'المحول المشترك جاهز':'غير متاح',checked,icon:'▶',action:'execution'},{name:'Paper Trading',state:trading.ok&&trading.data?.ok!==false?'ok':'warn',detail:trading.data?.provider||'وضع ورقي فقط',checked,icon:'◫',action:'paper'}];const box=$('#v24-integrations');if(box)box.innerHTML=integrationRows(integrationCache)}

function apps(s){const ids=['mueen','qaddha'],list=s.projects.filter(p=>ids.includes(p.id)||p.isApp);return `${top('APPS CENTER','مركز التطبيقات','حالة المشروع والتنفيذ وQA وروابط الإنتاج.',`<a class="v24-btn" href="apps.html">فتح المركز الكامل</a>`)}<div class="v24-app-grid">${list.map(p=>{const pt=s.tasks.filter(t=>t.projectId===p.id),latest=pt[0],links=projectLinks(p),lastCommit=pt.map(commit).find(Boolean);return `<article><header><div class="v24-app-logo">${esc(p.name.slice(0,1))}</div><div><span>${esc(p.status||'ACTIVE')}</span><h2>${esc(p.name)}</h2><p>${esc(p.phase||p.stage||'جاهز للعمل')}</p></div></header><div class="v24-app-stats"><span><b>${pt.filter(t=>activeStates.has(t.status)).length}</b> نشطة</span><span><b>${pt.filter(t=>t.status==='COMPLETED').length}</b> مكتملة</span><span><b>${esc(qa(latest))}</b> QA</span><span><b>${esc(lastCommit?lastCommit.slice(0,7):'—')}</b> Commit</span></div><div class="v24-app-owners">الموظفون: ${[...new Set(pt.map(t=>s.employees.find(e=>e.id===t.employeeId)?.name).filter(Boolean))].join('، ')||'غير مسند'}</div><footer>${links.live?`<a href="${esc(links.live)}" target="_blank">فتح التطبيق</a>`:''}${links.repo?`<a href="${esc(links.repo)}" target="_blank">GitHub</a>`:''}<button data-v24-project-task="${esc(p.id)}">إرسال مهمة</button><button data-v24-project-qa="${esc(p.id)}">QA</button><button data-v24-project-report="${esc(p.id)}">تقرير</button></footer></article>`}).join('')||empty('لا توجد تطبيقات مرتبطة','اربط مشروعًا كمشروع تطبيق.')}</div>`}

function activity(s){const all=[...s.activity.map(x=>({...x,group:(x.type||'ACTIVITY').toUpperCase()})),...s.notifications.map(x=>({...x,group:(x.type||'INFO').toUpperCase()}))].sort((a,b)=>Date.parse(b.at||b.createdAt||0)-Date.parse(a.at||a.createdAt||0)),filtered=activityFilter==='ALL'?all:all.filter(x=>x.group.includes(activityFilter));return `${top('AUDIT & REPORTS','النشاط والتقارير','سجل حقيقي قابل للتصفية مع التقارير الناتجة من المهام.',`<button class="v24-btn" data-v24-timeline>فتح Timeline</button>`)}<div class="v24-activity-filters">${['ALL','TASK','PROJECT','APPROVAL','DEPLOY','FINANCE','CONNECTION'].map(x=>`<button class="${activityFilter===x?'active':''}" data-v24-activity-filter="${x}">${x}</button>`).join('')}</div><section class="v24-split activity"><article class="v24-panel"><header><span>RECORDED EVENTS</span><h2>سجل النشاط</h2></header><div class="v24-feed">${filtered.slice(0,80).map(x=>`<div><i class="type-${esc(x.group)}"></i><p><b>${esc(x.text||x.title||'حدث مسجل')}</b><span>${esc(x.group)} · ${esc(ago(x.at||x.createdAt))}</span></p></div>`).join('')||empty('لا توجد أحداث','لن نعرض نشاطًا غير مسجل.')}</div></article><article class="v24-panel"><header><span>VERIFIED OUTPUTS</span><h2>التقارير</h2></header><div class="v24-mini-list">${s.reports.slice(0,30).map(r=>`<button data-report="${esc(r.id)}"><span><b>${esc(r.title)}</b><small>${esc(r.author||'AI')} · ${esc(ago(r.updatedAt||r.createdAt))}</small></span><i>${esc(r.stage||'محفوظ')}</i></button>`).join('')||empty('لا توجد تقارير','تظهر بعد تنفيذ مهمة ناجحة.')}</div></article></section>`}

function settings(s){const a={companyName:'NAWAF HQ',displayName:'NAWAF HQ',ceoName:'نواف',language:'ar',dateFormat:'sa',density:'comfortable',animation:'balanced',startup:'dashboard',autoRefresh:'15',backgroundIntensity:'70',glass:'72',blur:'18',uiScale:'100',iconStyle:'line',executionMode:'SAFE',timeout:'120',maxRetries:'2',...s.settings};const toggle=(name,label,checked,desc='')=>`<label class="v24-toggle"><span><b>${label}</b><small>${desc}</small></span><input type="checkbox" data-setting="${name}" ${checked?'checked':''}><i></i></label>`;return `${top('COMPANY CONFIGURATION','الإعدادات','إدارة الشركة والمظهر والتنفيذ والبيانات من مكان واحد.',`<button class="v24-btn primary" data-v24-save-settings>حفظ ومزامنة</button>`)}<div class="v24-settings"><nav>${[['general','عام'],['appearance','المظهر'],['execution','AI والتنفيذ'],['notifications','الإشعارات'],['data','البيانات'],['connections','الاتصالات']].map((x,i)=>`<button class="${i===0?'active':''}" data-v24-setting-tab="${x[0]}">${x[1]}</button>`).join('')}</nav><main><section data-setting-section="general" class="active"><h2>إعدادات الشركة</h2><div class="v24-form"><label>اسم الشركة<input data-setting="companyName" value="${esc(a.companyName)}"></label><label>اسم العرض<input data-setting="displayName" value="${esc(a.displayName)}"></label><label>اسم الرئيس التنفيذي<input data-setting="ceoName" value="${esc(a.ceoName)}"></label><label>اللغة<select data-setting="language"><option value="ar" ${a.language==='ar'?'selected':''}>العربية</option><option value="en" ${a.language==='en'?'selected':''}>English</option></select></label><label>كثافة الواجهة<select data-setting="density"><option value="comfortable" ${a.density==='comfortable'?'selected':''}>مريحة</option><option value="compact" ${a.density==='compact'?'selected':''}>مضغوطة</option></select></label><label>صفحة البدء<select data-setting="startup"><option value="dashboard">الرئيسية</option><option value="ceo" ${a.startup==='ceo'?'selected':''}>مركز CEO</option><option value="tasks" ${a.startup==='tasks'?'selected':''}>المهام</option></select></label><label>التحديث التلقائي<select data-setting="autoRefresh"><option value="15">كل 15 ثانية</option><option value="30" ${a.autoRefresh==='30'?'selected':''}>كل 30 ثانية</option><option value="off" ${a.autoRefresh==='off'?'selected':''}>إيقاف</option></select></label><label>صيغة التاريخ<select data-setting="dateFormat"><option value="sa">السعودية</option><option value="iso" ${a.dateFormat==='iso'?'selected':''}>ISO</option></select></label></div></section><section data-setting-section="appearance"><h2>المظهر المعتمد</h2><p class="v24-note">الثيم التنفيذي السينمائي الحالي هو الافتراضي.</p><div class="v24-form"><label>شدة الخلفية<input type="range" min="20" max="100" data-setting="backgroundIntensity" value="${esc(a.backgroundIntensity)}"></label><label>شفافية الزجاج<input type="range" min="35" max="95" data-setting="glass" value="${esc(a.glass)}"></label><label>الضبابية<input type="range" min="0" max="30" data-setting="blur" value="${esc(a.blur)}"></label><label>مقياس الواجهة<input type="range" min="85" max="115" data-setting="uiScale" value="${esc(a.uiScale)}"></label><label>نمط الأيقونات<select data-setting="iconStyle"><option value="line">خطية</option><option value="solid" ${a.iconStyle==='solid'?'selected':''}>ممتلئة</option></select></label><label>مستوى الحركة<select data-setting="animation"><option value="balanced">متوازن</option><option value="low" ${a.animation==='low'?'selected':''}>منخفض</option><option value="off" ${a.animation==='off'?'selected':''}>بدون حركة</option></select></label></div>${toggle('backgroundMotion','حركة الخلفية',a.backgroundMotion!==false,'تعطيلها يحسن الأداء على الأجهزة الضعيفة')}${toggle('reducedMotion','تقليل الحركة',a.reducedMotion===true)}${toggle('highContrast','تباين مرتفع',a.highContrast===true)}</section><section data-setting-section="execution"><h2>AI والتنفيذ</h2><div class="v24-form"><label>وضع التنفيذ<select data-setting="executionMode"><option value="SAFE">SAFE</option><option value="BALANCED" ${a.executionMode==='BALANCED'?'selected':''}>BALANCED</option><option value="AUTONOMOUS" ${a.executionMode==='AUTONOMOUS'?'selected':''}>AUTONOMOUS</option></select></label><label>مهلة التنفيذ بالثواني<input type="number" min="30" max="900" data-setting="timeout" value="${esc(a.timeout)}"></label><label>أقصى محاولات<input type="number" min="0" max="5" data-setting="maxRetries" value="${esc(a.maxRetries)}"></label><label>النموذج المفضل<input data-setting="preferredModel" value="${esc(a.preferredModel||'backend-managed')}" placeholder="حسب المتاح"></label><label>النموذج الاحتياطي<input data-setting="fallbackModel" value="${esc(a.fallbackModel||'')}"></label></div>${toggle('autoRetry','إعادة المحاولة تلقائيًا',a.autoRetry!==false)}${toggle('riskApproval','موافقة نواف للتغييرات الخطرة',a.riskApproval!==false)}${toggle('commitEvidence','إلزام دليل Commit للكود',a.commitEvidence!==false)}${toggle('qaRequired','إلزام QA قبل الاكتمال',a.qaRequired!==false)}${toggle('backgroundExecution','التنفيذ في الخلفية',a.backgroundExecution!==false)}${toggle('autoResume','استئناف المهام بعد الاتصال',a.autoResume!==false)}</section><section data-setting-section="notifications"><h2>الإشعارات</h2>${[['taskCompleted','اكتمال مهمة'],['taskFailed','فشل مهمة'],['approvalRequired','موافقة مطلوبة'],['connectionRequired','اتصال مطلوب'],['financeAlert','تنبيه مالي'],['projectChanged','تغيّر مشروع'],['secretarySummary','ملخص السكرتير'],['notificationSound','الصوت']].map(x=>toggle(x[0],x[1],a[x[0]]!==false)).join('')}</section><section data-setting-section="data"><h2>البيانات والمزامنة</h2><div class="v24-sync-card"><span><b>Cloud State</b><small>${window.HQCloud?.status?.().cloud?'متصل':'غير مؤكد'}</small></span><span><b>آخر مزامنة</b><small>${esc(window.HQCloud?.status?.().lastUpdatedAt||'غير متاح')}</small></span><span><b>Local State</b><small>${s.tasks.length} مهام · ${s.employees.length} موظفين</small></span></div><div class="v24-form-actions"><button class="v24-btn" data-v24-export>تصدير نسخة</button><label class="v24-btn file">استعادة نسخة<input type="file" data-v24-restore accept="application/json"></label><button class="v24-btn" data-v24-sync>مزامنة الآن</button><button class="v24-btn" data-v24-clear-cache>مسح الكاش الآمن</button></div><p class="v24-note">الاستعادة تدمج نسخة صحيحة بعد تأكيدك، ولا تمسح الأدلة تلقائيًا.</p></section><section data-setting-section="connections"><h2>الاتصالات</h2><p>اعرض الحالة الفعلية والأخطاء والصلاحيات من مركز التكاملات.</p><button class="v24-btn primary" data-v24-go="integrations">فتح مركز التكاملات</button></section></main></div>`}

function bind(root){root.querySelectorAll('[data-v24-employee]').forEach(b=>b.onclick=()=>openEmployee(b.dataset.v24Employee));root.querySelectorAll('[data-v24-project]').forEach(b=>b.onclick=()=>openProject(b.dataset.v24Project));root.querySelectorAll('[data-v24-task]').forEach(b=>b.onclick=()=>openTask(b.dataset.v24Task));root.querySelectorAll('[data-v24-project-task]').forEach(b=>b.onclick=()=>projectTask(b.dataset.v24ProjectTask));root.querySelectorAll('[data-v24-project-qa]').forEach(b=>b.onclick=()=>projectTask(b.dataset.v24ProjectQa,'شغّل فحص QA شامل على المشروع، وسجل النتائج والأدلة ولا تعلن النجاح بدون تحقق.','REVIEW'));root.querySelectorAll('[data-v24-project-report]').forEach(b=>b.onclick=()=>projectTask(b.dataset.v24ProjectReport,'أنشئ تقرير حالة تنفيذي للمشروع اعتمادًا على المهام والنتائج والأدلة المسجلة فقط.','REPORT'));root.querySelectorAll('[data-v24-setting-tab]').forEach(b=>b.onclick=()=>{root.querySelectorAll('[data-v24-setting-tab]').forEach(x=>x.classList.toggle('active',x===b));root.querySelectorAll('[data-setting-section]').forEach(x=>x.classList.toggle('active',x.dataset.settingSection===b.dataset.v24SettingTab))});root.querySelectorAll('[data-setting]').forEach(x=>x.onchange=()=>saveSetting(x));root.querySelector('[data-v24-save-settings]')?.addEventListener('click',()=>{window.HQCloud?.flush?.();notify('تم حفظ الإعدادات ومزامنتها')});root.querySelector('[data-v24-task-search]')?.addEventListener('input',e=>{taskQuery.text=e.target.value;clearTimeout(bind.q);bind.q=setTimeout(render,180)});root.querySelectorAll('[data-v24-task-filter]').forEach(x=>x.onchange=()=>{taskQuery[x.dataset.v24TaskFilter]=x.value;render()});root.querySelectorAll('[data-v24-task-preset]').forEach(b=>b.onclick=()=>{const v=b.dataset.v24TaskPreset;taskQuery.status=v==='COMPLETED'?'COMPLETED':'ALL';taskQuery.text='';taskQuery.project='ALL';taskQuery.employee='ALL';if(v==='ACTIVE')taskQuery.status='READY';if(v==='ATTENTION')taskQuery.text='';render()});root.querySelectorAll('[data-v24-activity-filter]').forEach(x=>x.onclick=()=>{activityFilter=x.dataset.v24ActivityFilter;render()});root.querySelector('[data-v24-refresh-integrations]')?.addEventListener('click',()=>{integrationCache=null;render()});root.querySelectorAll('[data-v24-integration-action]').forEach(b=>b.onclick=()=>integrationAction(b.dataset.v24IntegrationAction));root.querySelector('[data-v24-open-decisions]')?.addEventListener('click',()=>window.NawafHQV13?.openCenter?.());root.querySelector('[data-v24-morning]')?.addEventListener('click',()=>document.querySelector('[data-v15="brief"]')?.click()||window.NawafExecutiveSecretary?.open?.());root.querySelector('[data-v24-finance-open]')?.addEventListener('click',()=>window.NawafFinance?.open?.());root.querySelectorAll('[data-v24-finance-symbol]').forEach(b=>b.onclick=()=>window.NawafFinance?.open?.(b.dataset.v24FinanceSymbol));root.querySelector('[data-v24-timeline]')?.addEventListener('click',()=>window.NawafHQV23?.timeline?.());root.querySelector('[data-v24-export]')?.addEventListener('click',exportBackup);root.querySelector('[data-v24-restore]')?.addEventListener('change',restoreBackup);root.querySelector('[data-v24-sync]')?.addEventListener('click',async()=>{await window.HQCloud?.pull?.();notify('اكتملت محاولة المزامنة')});root.querySelector('[data-v24-clear-cache]')?.addEventListener('click',()=>{for(const k of Object.keys(sessionStorage))if(k.startsWith('hq-')||k.startsWith('nawaf-'))sessionStorage.removeItem(k);notify('تم مسح الكاش المؤقت بدون حذف بيانات الشركة')});root.querySelectorAll('[data-v24-go]').forEach(b=>b.onclick=()=>activate(b.dataset.v24Go));root.querySelector('#v24-employee-edit')?.addEventListener('submit',saveEmployee);root.querySelectorAll('[data-v24-duplicate]').forEach(b=>b.onclick=()=>duplicateEmployee(b.dataset.v24Duplicate));root.querySelectorAll('[data-v24-toggle]').forEach(b=>b.onclick=()=>toggleEmployee(b.dataset.v24Toggle));root.querySelectorAll('[data-v24-delete-employee]').forEach(b=>b.onclick=()=>deleteEmployee(b.dataset.v24DeleteEmployee));root.querySelectorAll('[data-v24-direct],[data-v24-assign]').forEach(b=>b.onclick=()=>employeeTask(b.dataset.v24Direct||b.dataset.v24Assign));root.querySelectorAll('[data-v24-task-action]').forEach(b=>b.onclick=()=>taskAction(b.dataset.id,b.dataset.v24TaskAction));root.querySelectorAll('[data-v24-reassign]').forEach(b=>b.onclick=()=>reassign(b.dataset.v24Reassign));root.querySelectorAll('[data-v24-copy]').forEach(b=>b.onclick=()=>copyResult(b.dataset.v24Copy))}
function integrationAction(id){if(id==='sync'){window.HQCloud?.pull?.().then(()=>notify('تم فحص المزامنة'));return}if(id==='health'){integrationCache=null;render();return}const item=(integrationCache||[]).find(x=>x.action===id),s=ensure(read()),req=s.connectionRequests.find(x=>['PENDING','APPROVED'].includes(x.status)&&String(x.provider||x.providerName||x.tool||'').toLowerCase().includes(id));modal(item?.name||'التكامل',`<div class="v24-current"><small>الحالة الفعلية</small><b>${esc(item?.state==='ok'?'متصل':item?.state==='warn'?'يحتاج انتباه':'غير متصل')}</b><span>${esc(item?.detail||'لا توجد تفاصيل من الخادم')}</span></div>${req?`<section class="v24-task-detail warning"><h3>طلب ربط مسجل</h3><p>${esc(req.reason||'هذا الاتصال مطلوب لمهمة حقيقية.')}</p><small>${esc((req.permissions||[]).join('، '))}</small><div class="v24-form-actions">${req.setupUrl?`<a class="v24-btn primary" href="${esc(req.setupUrl)}" target="_blank" rel="noopener">فتح إعداد الربط</a>`:''}<button class="v24-btn" data-conn-approve="${esc(req.id)}">موافقة</button><button class="v24-btn" data-conn-decline="${esc(req.id)}">رفض</button></div></section>`:'<p class="v24-note">لا يوجد طلب ربط أو رابط إعداد مسجل حاليًا. لن نعرض اتصالًا وهميًا؛ أضف بيانات الخدمة في بيئة الخادم ثم أعد الفحص.</p>'}`)}
function saveSetting(el){const s=ensure(read()),value=el.type==='checkbox'?el.checked:el.value;s.settings[el.dataset.setting]=value;s.settings.updatedAt=now();write(s,'settings-updated');applySettings(s.settings)}
function applySettings(a={}){document.documentElement.style.setProperty('--v24-ui-scale',`${Number(a.uiScale||100)/100}`);document.documentElement.style.setProperty('--v24-glass',`${Number(a.glass||72)/100}`);document.documentElement.style.setProperty('--v24-blur',`${Number(a.blur||18)}px`);document.documentElement.dataset.v24Density=a.density||'comfortable';document.documentElement.dataset.v21Motion=(a.reducedMotion||a.animation==='off'||a.backgroundMotion===false)?'off':'on';document.documentElement.classList.toggle('v24-high-contrast',a.highContrast===true)}
function saveEmployee(ev){ev.preventDefault();const f=new FormData(ev.currentTarget),s=ensure(read()),e=s.employees.find(x=>x.id===f.get('id'));if(!e)return;e.name=String(f.get('name')).trim();e.role=String(f.get('role')).trim();e.department=String(f.get('department')).trim();e.accent=String(f.get('accent'));e.description=String(f.get('description')).trim();e.skills=String(f.get('skills')).split(',').map(x=>x.trim()).filter(Boolean);e.instructions=String(f.get('instructions')).trim();e.permissions=f.getAll('perm');e.updatedAt=now();audit(s,`تم تحديث ملف الموظف ${e.name}`);write(s,'employee-updated');$('#v24-modal')?.classList.remove('show');notify('تم حفظ ملف الموظف')}
function duplicateEmployee(id){const s=ensure(read()),e=s.employees.find(x=>x.id===id);if(!e)return;const c={...e,id:uid('emp'),name:`${e.name} — نسخة`,status:'READY',task:'',createdAt:now(),updatedAt:now(),custom:true};s.employees.push(c);audit(s,`تم إنشاء ملف موظف جديد من ${e.name}`);write(s,'employee-duplicated');$('#v24-modal')?.classList.remove('show');notify('تم نسخ ملف الموظف')}
function toggleEmployee(id){const s=ensure(read()),e=s.employees.find(x=>x.id===id);if(!e)return;e.disabled=!e.disabled;e.status=e.disabled?'PAUSED':'READY';e.updatedAt=now();audit(s,`${e.disabled?'تم تعطيل':'تم تفعيل'} الموظف ${e.name}`);write(s,'employee-toggled');$('#v24-modal')?.classList.remove('show');notify(e.disabled?'تم التعطيل المؤقت':'تم التفعيل')}
function deleteEmployee(id){const s=ensure(read()),e=s.employees.find(x=>x.id===id);if(!e||!String(id).startsWith('emp'))return;if(s.tasks.some(t=>t.employeeId===id&&activeStates.has(t.status))){notify('لا يمكن حذف موظف لديه مهمة نشطة');return}e.deletedAt=now();e.disabled=true;e.status='PAUSED';e.updatedAt=e.deletedAt;audit(s,`تم حذف ملف الموظف المخصص ${e.name} حذفًا آمنًا`);write(s,'employee-safe-delete');$('#v24-modal')?.classList.remove('show');notify('تم الحذف الآمن مع حفظ السجل')}
function projectTask(projectId,prefill='',kind='CUSTOM'){const s=ensure(read()),p=s.projects.find(x=>x.id===projectId);if(!p)return;const m=modal(`مهمة على ${p.name}`,`<form id="v24-project-task-form" class="v24-form"><input type="hidden" name="projectId" value="${esc(projectId)}"><input type="hidden" name="kind" value="${esc(kind)}"><label>الموظف<select name="employeeId">${s.employees.filter(e=>!e.deletedAt&&!e.disabled).map(e=>`<option value="${esc(e.id)}">${esc(e.name)} — ${esc(e.role||'')}</option>`).join('')}</select></label><label class="full">التعليمات<textarea name="details" rows="7" required>${esc(prefill)}</textarea></label><div class="full v24-form-actions"><button class="v24-btn primary" type="submit">إنشاء وتشغيل</button><button class="v24-btn" type="button" data-v24-close>إلغاء</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);createTask(String(f.get('employeeId')),projectId,String(f.get('details')).trim(),String(f.get('kind')));m.classList.remove('show')}}
function employeeTask(employeeId){const s=ensure(read()),e=s.employees.find(x=>x.id===employeeId);if(!e)return;const m=modal(`أمر مباشر إلى ${e.name}`,`<form class="v24-form"><label>المشروع<select name="projectId"><option value="">عام</option>${s.projects.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label class="full">الأمر<textarea name="details" rows="7" required></textarea></label><div class="full v24-form-actions"><button class="v24-btn primary">إنشاء وتشغيل</button></div></form>`);m.querySelector('form').onsubmit=x=>{x.preventDefault();const f=new FormData(x.currentTarget);createTask(employeeId,String(f.get('projectId')),String(f.get('details')).trim());m.classList.remove('show')}}
function createTask(employeeId,projectId,details,kind='CUSTOM'){if(!details)return;const s=ensure(read()),e=s.employees.find(x=>x.id===employeeId);if(!e)return;const t={id:uid('t'),title:details.slice(0,100),details,employeeId,projectId,status:'READY',kind,createdBy:'NAWAF',createdAt:now(),updatedAt:now(),retryCount:0};s.tasks.unshift(t);e.status='READY';e.task=t.title;e.updatedAt=now();audit(s,`تم تكليف ${e.name}: ${t.title}`,'TASK');write(s,'task-created-v24');notify(`تم إرسال المهمة إلى ${e.name}`);setTimeout(()=>window.NawafAgents?.runTask?.(t.id).catch(()=>notify('حُفظت المهمة، ومحرك التنفيذ يحتاج إعادة محاولة')),150)}
function taskAction(id,action){const s=ensure(read()),t=s.tasks.find(x=>x.id===id);if(!t)return;if(action==='pause'){t.status='PAUSED';t.pausedAt=now()}if(action==='resume'||action==='retry'){t.status='READY';t.retryCount=(t.retryCount||0)+(action==='retry'?1:0);delete t.blockedReason;delete t.blockerType;t.resumedAt=now()}if(action==='archive')t.archivedAt=now();t.updatedAt=now();audit(s,`${action==='archive'?'أرشفة':action==='pause'?'إيقاف':action==='resume'?'استئناف':'إعادة محاولة'} المهمة: ${t.title}`,'TASK');write(s,`task-${action}`);$('#v24-modal')?.classList.remove('show');if(['resume','retry'].includes(action))setTimeout(()=>window.NawafAgents?.runTask?.(id).catch(()=>{}),150);notify('تم تحديث المهمة')}
function reassign(id){const s=ensure(read()),t=s.tasks.find(x=>x.id===id);if(!t)return;const m=modal('إعادة تعيين المهمة',`<form class="v24-form"><label class="full">الموظف<select name="employeeId">${s.employees.filter(e=>!e.deletedAt&&!e.disabled).map(e=>`<option value="${esc(e.id)}" ${e.id===t.employeeId?'selected':''}>${esc(e.name)} — ${esc(e.role||'')}</option>`).join('')}</select></label><div class="full v24-form-actions"><button class="v24-btn primary">حفظ التعيين</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const q=ensure(read()),z=q.tasks.find(x=>x.id===id);z.employeeId=String(new FormData(e.currentTarget).get('employeeId'));z.updatedAt=now();audit(q,`تمت إعادة تعيين المهمة: ${z.title}`,'TASK');write(q,'task-reassigned');m.classList.remove('show');notify('تمت إعادة التعيين')}}
async function copyResult(id){const t=ensure(read()).tasks.find(x=>x.id===id),text=t?.aiResult?.deliverable||t?.aiResult?.summary||t?.blockedReason||'';try{await navigator.clipboard.writeText(text);notify('تم نسخ النتيجة')}catch{notify('تعذر النسخ من المتصفح')}}
function exportBackup(){const s=ensure(read()),blob=new Blob([JSON.stringify({format:'NAWAF_HQ_BACKUP_V1',exportedAt:now(),state:s},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`nawaf-hq-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('تم تجهيز النسخة الاحتياطية')}
function restoreBackup(ev){const file=ev.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(reader.result),incoming=parsed.state||parsed;if(!incoming||!Array.isArray(incoming.tasks)||!Array.isArray(incoming.employees))throw new Error('INVALID');if(!confirm('استعادة هذه النسخة ودمجها مع حالة الشركة الحالية؟'))return;const current=ensure(read()),merged={...current,...incoming,employees:mergeById(current.employees,incoming.employees),projects:mergeById(current.projects,incoming.projects),tasks:mergeById(current.tasks,incoming.tasks),reports:mergeById(current.reports,incoming.reports),activity:mergeById(current.activity,incoming.activity),settings:{...current.settings,...incoming.settings,updatedAt:now()}};audit(merged,'تمت استعادة نسخة احتياطية يدويًا','DATA');write(merged,'backup-restored');notify('تمت الاستعادة والمزامنة')}catch{notify('ملف النسخة غير صالح')}};reader.readAsText(file)}
function mergeById(a=[],b=[]){const m=new Map();for(const x of [...a,...b])if(x?.id){const old=m.get(x.id),ot=Date.parse(old?.updatedAt||old?.createdAt||0),nt=Date.parse(x.updatedAt||x.createdAt||0);if(!old||nt>=ot)m.set(x.id,x)}return [...m.values()]}
document.addEventListener('click',e=>{const t=e.target.closest('.v24-workspace [data-v24-task]');if(!t)return;e.preventDefault();e.stopPropagation();openTask(t.dataset.v24Task)},true);
document.addEventListener('keydown',e=>{if(!['Enter',' '].includes(e.key))return;const t=e.target.closest('.v24-workspace [data-v24-task]');if(!t)return;e.preventDefault();openTask(t.dataset.v24Task)},true);
document.addEventListener('click',e=>{const custom=e.target.closest('[data-v24-page]');if(custom){e.preventDefault();e.stopImmediatePropagation();activate(custom.dataset.v24Page);return}const builtin=e.target.closest('.v8-side [data-view]');if(builtin){const mapped=PAGE_MAP[builtin.dataset.view];if(mapped){e.preventDefault();e.stopImmediatePropagation();activate(mapped)}else{page=null;document.body.classList.remove('v24-active')}return}},true);
let refreshTimer;window.addEventListener('nawaf:state-updated',()=>{clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>{mountNav();if(page)render()},130)});
function boot(){mountNav();applySettings(ensure(read()).settings);new MutationObserver(()=>{mountNav();if(page&&main()?.dataset.v24Page!==page)render()}).observe($('#app')||document.body,{childList:true,subtree:true})}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot();
window.NawafHQV24={activate,settings:()=>activate('settings'),employees:()=>activate('employees'),projects:()=>activate('projects'),tasks:()=>activate('tasks'),secretary:()=>activate('secretary'),finance:()=>activate('finance'),integrations:()=>activate('integrations'),apps:()=>activate('apps'),ceo:()=>activate('ceo'),exportBackup,restoreBackup,openEmployee};
})();
